    if istemeyi == "transfer":
        oran = 0.001 # Hayat Finans örneğine %0,1 (yani 0.001) uyumludur
    elif istemeyi == "harcama":
        oran = 0.01  # ParafPara/Hayat Pay örneğinde %1'lik orana göre belirlenebilirken (%247'e varan bir durum varsa bu değer değiştirilir, ancak verideki en yüksek sabit örnek %1'dir)
    else:
        raise ValueError("Hesaplama için 'transfer', 'harcama' veya benzeri geçerli bir isteme ihtiyacınız var.") # Varsayılan 0.1 oranı (örnek olarak hayatta finans örneğinde geçilen %0,1 yerine belirlenebilir)

    if istemeyi == "transfer": 
        orani_kaynak = 0.001; else: orani_kaynak = 0.01
